int main() {
    string input;
    getline(cin, input);
    // 统计各个字符出现的数量
    unordered_map<char,int> charCount;
    // 每个字符保留个数
    unordered_map<char,int> saveCount;
    int n = input.size();
    // 记录某个位置字符是否被删除
    vector<bool> deleteFlag(n, false);
    for (int i = 0; i < n; i++) {
        char c = input[i];
        charCount[c]++;
    }
    // 单调栈 递减
    stack<char> stk;
    for (int i = 0; i < n; i++) {
        char c = input[i];
        // 该字符已经决定保留2个，后续出现的字符不再考虑
        if (saveCount[c] == 2) {
            charCount[c]--;
            continue;
        }
        // 比较当前字符和栈顶的数字
        while (!stk.empty()) {
            char top = stk.top();
            // 栈顶元素被弹出后 saveCount[top] - 1  + charCount[top] 要大于等于二 否则不能弹出
            if (top < c && charCount[top] + (saveCount[top] - 1) >= 2) {
                stk.pop();
                saveCount[top]--;
            } else {
                break;
            }
        } 
        // 保留当前数字
        stk.push(c);
        // 剩余数量减少
        charCount[c]--;
        // 保存个数更新
        saveCount[c]++;
    }
    string res = "";
    while (!stk.empty()) {
        char c = stk.top();
        stk.pop();
        res.push_back(c);
    }
    reverse(res.begin(), res.end());
    cout << res;
    return 0;
}
