import java.util.*;
​
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        String input = sc.nextLine();
​
        // 统计每个字符出现的数量
        Map<Character, Integer> charCount = new HashMap<>();
        // 每个字符保留个数
        Map<Character, Integer> saveCount = new HashMap<>();
        int n = input.length();
​
        for (int i = 0; i < n; i++) {
            char c = input.charAt(i);
            charCount.put(c, charCount.getOrDefault(c, 0) + 1);
        }
​
        // 单调栈，维护字典序更大的字符
        Deque<Character> stack = new ArrayDeque<>();
        for (int i = 0; i < n; i++) {
            char c = input.charAt(i);
            saveCount.putIfAbsent(c, 0);
​
            // 如果当前字符已经保留两个，不再保留
            if (saveCount.get(c) == 2) {
                charCount.put(c, charCount.get(c) - 1);
                continue;
            }
​
            // 弹出栈顶元素，前提是它可以保证仍然有两个保留
            while (!stack.isEmpty()) {
                char top = stack.peekLast();
                if (top < c && charCount.get(top) + saveCount.get(top) - 1 >= 2) {
                    stack.pollLast();
                    saveCount.put(top, saveCount.get(top) - 1);
                } else {
                    break;
                }
            }
​
            // 当前字符入栈
            stack.addLast(c);
            charCount.put(c, charCount.get(c) - 1);
            saveCount.put(c, saveCount.get(c) + 1);
        }
​
        // 构建结果
        StringBuilder res = new StringBuilder();
        for (char c : stack) {
            res.append(c);
        }
        System.out.println(res.toString());
    }
}
