const readline = require('readline');
​
const rl = readline.createInterface({
    input: process.stdin,
    output: process.stdout
});
​
rl.on('line', function (input) {
    const charCount = new Map();
    const saveCount = new Map();
    const stack = [];
​
    for (let c of input) {
        charCount.set(c, (charCount.get(c) || 0) + 1);
    }
​
    for (let c of input) {
        if (!saveCount.has(c)) saveCount.set(c, 0);
​
        // 如果该字符已经保留了两个，就不再保留
        if (saveCount.get(c) === 2) {
            charCount.set(c, charCount.get(c) - 1);
            continue;
        }
​
        // 弹出比当前字符小，且剩余总数可满足2的字符
        while (stack.length > 0) {
            let top = stack[stack.length - 1];
            if (top < c && charCount.get(top) + saveCount.get(top) - 1 >= 2) {
                stack.pop();
                saveCount.set(top, saveCount.get(top) - 1);
            } else {
                break;
            }
        }
​
        stack.push(c);
        charCount.set(c, charCount.get(c) - 1);
        saveCount.set(c, saveCount.get(c) + 1);
    }
​
    console.log(stack.join(''));
    rl.close();
});
