package main
​
import (
    "bufio"
    "fmt"
    "os"
    "strings"
)
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    input, _ := reader.ReadString('\n')
    input = strings.TrimSpace(input)
​
    // 统计每个字符出现次数
    charCount := make(map[rune]int)
    saveCount := make(map[rune]int)
​
    for _, c := range input {
        charCount[c]++
    }
​
    stack := []rune{}
​
    for _, c := range input {
        if saveCount[c] == 2 {
            charCount[c]--
            continue
        }
​
        // 弹出比当前字符小，且剩余足够保留的字符
        for len(stack) > 0 {
            top := stack[len(stack)-1]
            if top < c && charCount[top]+saveCount[top]-1 >= 2 {
                stack = stack[:len(stack)-1]
                saveCount[top]--
            } else {
                break
            }
        }
​
        stack = append(stack, c)
        charCount[c]--
        saveCount[c]++
    }
​
    fmt.Println(string(stack))
}
